TEST(PairingTest, OutOfOrderCalls) {
  boost::property_tree::ptree tree;

  setup(PRIVATE_KEY, PUBLIC_CERT);

  pair_session_t sess {};

  clientchallenge(sess, tree, "test");
  ASSERT_FALSE(tree.get<int>("root.paired") == 1);

  serverchallengeresp(sess, tree, "test");
  ASSERT_FALSE(tree.get<int>("root.paired") == 1);

  clientpairingsecret(sess, tree, "test");
  ASSERT_FALSE(tree.get<int>("root.paired") == 1);

  // This should work, it's the first time we call it
  sess.async_insert_pin.salt = "ff5dc6eda99339a8a0793e216c4257c4";
  getservercert(sess, tree, "test");
  ASSERT_TRUE(tree.get<int>("root.paired") == 1);

  // Calling it again should fail
  getservercert(sess, tree, "test");
  ASSERT_FALSE(tree.get<int>("root.paired") == 1);
}

namespace {
  const std::string SALT = "ff5dc6eda99339a8a0793e216c4257c4";
  const std::string OTHER_SALT = "00112233445566778899aabbccddeeff";
  const std::string CERT_HEX = "AABB";
  const std::string OTHER_CERT_HEX = "CCDD";

  args_t request_args(const std::string &cert_hex, const std::string &salt) {
    return {{"devicename", "test"}, {"clientcert", cert_hex}, {"salt", salt}};
  }

  pair_session_t &add_session(const std::string &id, PAIR_PHASE phase = PAIR_PHASE::NONE) {
    return map_id_sess.emplace(
      id,
      pair_session_t {
        .client = {.uniqueID = id, .cert = PUBLIC_CERT, .name = "test"},
        .async_insert_pin = {.salt = SALT},
        .last_phase = phase
      }
    ).first->second;
  }

  /**
   * Moves a session past PAIRING_PROMPT_GRACE, without it expiring.
   */
  void age_past_prompt_grace(pair_session_t &sess) {
    sess.expires_at = std::chrono::steady_clock::now() + PAIRING_SESSION_TIMEOUT - PAIRING_PROMPT_GRACE - 1s;
  }

  /**
   * Runs the client side of the same handshake vectors as PairingTest. This removes the session.
   */
  void finish_handshake(pair_session_t &sess) {
    boost::property_tree::ptree tree;
    clientchallenge(sess, tree, util::from_hex_vec("741CD3D6890C16DA39D53BCA0893AAF0", true));
    serverchallengeresp(sess, tree, util::from_hex_vec("920BABAE9F7599AA1CA8EC87FB3454C91872A7D8D5127DDC176C2FDAE635CF7A", true));
    sess.serverchallenge = util::from_hex_vec("AAAAAAAAAAAAAAAA", true);
    clientpairingsecret(
      sess,
      tree,
      util::from_hex_vec("000102030405060708090A0B0C0D0EFF"  // secret
                         "",
                         true)
    );
  }

  /**
   * Runs the same handshake vectors as PairingTest against a session in the map,
   * while another thread waits in pin().
   */
  void expect_pin_result_from_handshake(const std::string &entered_pin, bool expected) {
    const auto clients_before = get_all_clients().size();
    add_session("1234");

    auto result = std::async(std::launch::async, [&entered_pin]() {
      return pin(entered_pin, "test");
    });

    // pin() takes the session out of phase NONE before it starts waiting
    const auto give_up = std::chrono::steady_clock::now() + 5s;
    bool got_pin = false;
    while (!got_pin && std::chrono::steady_clock::now() < give_up) {
      {
        std::scoped_lock lock {map_id_sess_mutex};
        got_pin = map_id_sess.at("1234").last_phase == PAIR_PHASE::GETSERVERCERT;
      }
      std::this_thread::sleep_for(1ms);
    }
    ASSERT_TRUE(got_pin);

    {
      std::scoped_lock lock {map_id_sess_mutex};
      finish_handshake(map_id_sess.at("1234"));
    }

    EXPECT_EQ(result.get(), expected);
    EXPECT_TRUE(map_id_sess.empty());
    EXPECT_EQ(get_all_clients().size(), clients_before + (expected ? 1 : 0));
  }
}  // namespace

class PairingSessionTest: public testing::Test {
protected:
  void SetUp() override {
    // Keep pairing results out of the state file
    config::sunshine.flags.set(config::flag::FRESH_STATE);
    setup(PRIVATE_KEY, PUBLIC_CERT);
    map_id_sess.clear();
  }

  void TearDown() override {
    map_id_sess.clear();
    config::stream.ping_timeout = original_ping_timeout;
  }

  const std::chrono::milliseconds original_ping_timeout = config::stream.ping_timeout;
  boost::property_tree::ptree tree;
};

TEST_F(PairingSessionTest, PinWithShortSaltFailsAndDropsSession) {
  add_session("1234").async_insert_pin.salt = "ab";

  EXPECT_FALSE(pin("5338", "test"));
  EXPECT_TRUE(map_id_sess.empty());
}

TEST_F(PairingSessionTest, PinIgnoresSessionPastPhaseNone) {
  add_session("1234", PAIR_PHASE::GETSERVERCERT);

  EXPECT_FALSE(pin("5338", "test"));
  EXPECT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::GETSERVERCERT);
}

TEST_F(PairingSessionTest, PinRefusesWhenTwoSessionsAreWaiting) {
  add_session("1234");
  add_session("5678");

  EXPECT_FALSE(pin("5338", "test"));
  EXPECT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::NONE);
  EXPECT_EQ(map_id_sess.at("5678").last_phase, PAIR_PHASE::NONE);
}

TEST_F(PairingSessionTest, PinRefusesWithoutSession) {
  EXPECT_FALSE(pin("5338", "test"));
}

TEST_F(PairingSessionTest, PinTimeoutKeepsSessionForLateHandshake) {
  config::stream.ping_timeout = 50ms;
  const auto clients_before = get_all_clients().size();
  add_session("1234");

  EXPECT_FALSE(pin("5338", "test"));
  ASSERT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::GETSERVERCERT);

  finish_handshake(map_id_sess.at("1234"));

  EXPECT_TRUE(map_id_sess.empty());
  EXPECT_EQ(get_all_clients().size(), clients_before + 1);
}

TEST_F(PairingSessionTest, PinSkipsAbandonedSessionWhenNewerOneWaits) {
  config::stream.ping_timeout = 50ms;
  age_past_prompt_grace(add_session("abandoned"));
  add_session("1234");

  EXPECT_FALSE(pin("5338", "test"));

  EXPECT_EQ(map_id_sess.at("abandoned").last_phase, PAIR_PHASE::NONE);
  EXPECT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::GETSERVERCERT);
}

TEST_F(PairingSessionTest, PinStillReachesLoneSessionPastGrace) {
  config::stream.ping_timeout = 50ms;
  age_past_prompt_grace(add_session("1234"));

  EXPECT_FALSE(pin("5338", "test"));

  EXPECT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::GETSERVERCERT);
}

TEST_F(PairingSessionTest, PinRefusesWhenTwoSessionsPastGraceAreWaiting) {
  age_past_prompt_grace(add_session("1234"));
  age_past_prompt_grace(add_session("5678"));

  EXPECT_FALSE(pin("5338", "test"));

  EXPECT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::NONE);
  EXPECT_EQ(map_id_sess.at("5678").last_phase, PAIR_PHASE::NONE);
}

TEST_F(PairingSessionTest, PinReturnsTrueAfterHandshakeWithRightPin) {
  expect_pin_result_from_handshake("5338", true);
}

TEST_F(PairingSessionTest, PinReturnsFalseAfterHandshakeWithWrongPin) {
  expect_pin_result_from_handshake("0000", false);
}

TEST_F(PairingSessionTest, RetryReplacesSessionPastPhaseNone) {
  auto completion = add_session("1234", PAIR_PHASE::CLIENTCHALLENGE).completion;

  auto sess = start_pair_session(request_args(CERT_HEX, OTHER_SALT), "1234", tree);

  ASSERT_NE(sess, nullptr);
  EXPECT_EQ(sess->last_phase, PAIR_PHASE::NONE);
  EXPECT_EQ(sess->async_insert_pin.salt, OTHER_SALT);
  EXPECT_EQ(map_id_sess.size(), 1u);
  // A pin() call still waiting on the old session must not wait for its timeout
  EXPECT_EQ(completion->result, false);
}

TEST_F(PairingSessionTest, StaleSessionDoesNotConsumeOtp) {
  const std::string passphrase = "passphrase";
  const auto otp = request_otp(passphrase, "otp device");
  add_session("1234", PAIR_PHASE::GETSERVERCERT);

  auto hash = util::hex(crypto::hash(otp + SALT + passphrase), true);
  auto args = request_args(CERT_HEX, SALT);
  args.emplace("otpauth", std::string {hash.to_string_view()});

  EXPECT_EQ(start_pair_session(args, "1234", tree), nullptr);
  EXPECT_EQ(tree.get<int>("root.paired"), 1);
  EXPECT_EQ(map_id_sess.at("1234").last_phase, PAIR_PHASE::GETSERVERCERT);
  EXPECT_EQ(map_id_sess.at("1234").client.name, "otp device");
}

TEST_F(PairingSessionTest, DifferentCertCannotTakeOverWaitingSession) {
  ASSERT_NE(start_pair_session(request_args(CERT_HEX, SALT), "1234", tree), nullptr);
  const auto cert = map_id_sess.at("1234").client.cert;

  EXPECT_EQ(start_pair_session(request_args(OTHER_CERT_HEX, OTHER_SALT), "1234", tree), nullptr);

  EXPECT_EQ(tree.get<int>("root.<xmlattr>.status_code"), 409);
  EXPECT_EQ(map_id_sess.at("1234").client.cert, cert);
  EXPECT_EQ(map_id_sess.at("1234").async_insert_pin.salt, SALT);
}

TEST_F(PairingSessionTest, DifferentCertDisplacesAbandonedSession) {
  ASSERT_NE(start_pair_session(request_args(CERT_HEX, SALT), "1234", tree), nullptr);
  auto &abandoned = map_id_sess.at("1234");
  age_past_prompt_grace(abandoned);
  const auto completion = abandoned.completion;

  ASSERT_NE(start_pair_session(request_args(OTHER_CERT_HEX, OTHER_SALT), "1234", tree), nullptr);

  EXPECT_EQ(map_id_sess.size(), 1u);
  EXPECT_EQ(map_id_sess.at("1234").async_insert_pin.salt, OTHER_SALT);
  EXPECT_EQ(completion->result, false);
}

TEST_F(PairingSessionTest, SameCertReplacesWaitingSession) {
  ASSERT_NE(start_pair_session(request_args(CERT_HEX, SALT), "1234", tree), nullptr);

  ASSERT_NE(start_pair_session(request_args(CERT_HEX, OTHER_SALT), "1234", tree), nullptr);

  EXPECT_EQ(map_id_sess.size(), 1u);
  EXPECT_EQ(map_id_sess.at("1234").async_insert_pin.salt, OTHER_SALT);
}

TEST_F(PairingSessionTest, BadArgumentsLeaveNoSession) {
  EXPECT_EQ(start_pair_session({{"devicename", "test"}, {"clientcert", CERT_HEX}}, "1234", tree), nullptr);
  EXPECT_EQ(tree.get<int>("root.<xmlattr>.status_code"), 400);

  EXPECT_EQ(start_pair_session(request_args(CERT_HEX, "ab"), "1234", tree), nullptr);
  EXPECT_EQ(tree.get<int>("root.<xmlattr>.status_code"), 400);

  EXPECT_THROW(start_pair_session({{"devicename", "test"}, {"salt", SALT}}, "1234", tree), std::out_of_range);

  EXPECT_TRUE(map_id_sess.empty());
}

TEST_F(PairingSessionTest, NewSessionGetsDeadline) {
  const auto before = std::chrono::steady_clock::now();

  auto sess = start_pair_session(request_args(CERT_HEX, SALT), "1234", tree);

  ASSERT_NE(sess, nullptr);
  EXPECT_GE(sess->expires_at, before + PAIRING_SESSION_TIMEOUT);
  EXPECT_LE(sess->expires_at, std::chrono::steady_clock::now() + PAIRING_SESSION_TIMEOUT);
}

TEST_F(PairingSessionTest, ExpiredSessionIsDropped) {
  auto &sess = add_session("1234");
  sess.expires_at = std::chrono::steady_clock::now() - 1s;
  auto completion = sess.completion;

  // The expired session would otherwise take this PIN
  EXPECT_FALSE(pin("5338", "test"));

  EXPECT_TRUE(map_id_sess.empty());
  EXPECT_EQ(completion->result, false);
}

TEST_F(PairingSessionTest, SessionCountIsCapped) {
  for (std::size_t i = 0; i < MAX_PENDING_PAIRING_SESSIONS; ++i) {
    add_session(std::to_string(i), PAIR_PHASE::GETSERVERCERT);
  }

  EXPECT_EQ(start_pair_session(request_args(CERT_HEX, SALT), "new", tree), nullptr);
  EXPECT_EQ(tree.get<int>("root.<xmlattr>.status_code"), 503);
  EXPECT_EQ(map_id_sess.size(), MAX_PENDING_PAIRING_SESSIONS);

  // A retry frees its own slot first
  EXPECT_NE(start_pair_session(request_args(CERT_HEX, SALT), "0", tree), nullptr);
}

class ClientAuthStateTest: public testing::Test {
protected:
  void SetUp() override {
    std::filesystem::create_directories(dir);
    config::nvhttp.file_state = state_file.string();
    config::sunshine.flags.reset(config::flag::FRESH_STATE);
    http::unique_id = uuid_util::uuid_t::generate().string();

    // Clients left in memory by the pairing tests
    erase_all_clients();

    add_authorized_client(make_client(other_cert()));
    target = make_client(PUBLIC_CERT);
    add_authorized_client(target);
    ASSERT_TRUE(trusted(PUBLIC_CERT));
    ASSERT_TRUE(trusted(other_cert()));
  }

  void TearDown() override {
    erase_all_clients();
    config::nvhttp.file_state = original_file_state;
    config::sunshine.flags = original_flags;
    http::unique_id = original_unique_id;
    http::uuid = original_uuid;

    std::error_code ec;
    std::filesystem::remove_all(dir, ec);
  }

  // Generating a key is slow, and one is enough for every test
  static const std::string &other_cert() {
    static const std::string cert = crypto::gen_creds("other", 2048).x509;
    return cert;
  }

  static crypto::p_named_cert_t make_client(const std::string &cert) {
    auto client = std::make_shared<crypto::named_cert_t>();
    client->name = "test";
    client->cert = cert;
    client->uuid = uuid_util::uuid_t::generate().string();
    return client;
  }

  static bool trusted(const std::string &cert) {
    crypto::p_named_cert_t named_cert;
    return verify_client_cert(crypto::x509(cert).get(), named_cert) == nullptr;
  }

  void damage_state_file() const {
    std::ofstream(state_file) << "{ not json";
  }

  // file_handler::write_file writes to this path first. The state file stays valid and holds the old clients.
  void block_state_writes() const {
    std::filesystem::create_directory(state_file.string() + ".tmp");
  }

  const std::filesystem::path dir = std::filesystem::temp_directory_path() / ("apollo-client-auth-" + uuid_util::uuid_t::generate().string());
  const std::filesystem::path state_file = dir / "state.json";
  const std::string original_file_state = config::nvhttp.file_state;
  const decltype(config::sunshine.flags) original_flags = config::sunshine.flags;
  const std::string original_unique_id = http::unique_id;
  const uuid_util::uuid_t original_uuid = http::uuid;
  crypto::p_named_cert_t target;
};

TEST_F(ClientAuthStateTest, UnpairSavesAndRevokes) {
  EXPECT_TRUE(unpair_client(target->uuid));
  EXPECT_FALSE(trusted(PUBLIC_CERT));
  EXPECT_TRUE(trusted(other_cert()));

  load_state();
  EXPECT_FALSE(trusted(PUBLIC_CERT));
  EXPECT_EQ(get_all_clients().size(), 1u);
}

TEST_F(ClientAuthStateTest, UnpairWithDamagedFileRevokesAndFails) {
  damage_state_file();

  EXPECT_FALSE(unpair_client(target->uuid));
  EXPECT_FALSE(trusted(PUBLIC_CERT));
  EXPECT_TRUE(trusted(other_cert()));
  EXPECT_EQ(get_all_clients().size(), 1u);
}

TEST_F(ClientAuthStateTest, UnpairWithFailedWriteRevokesAndFails) {
  block_state_writes();

  EXPECT_FALSE(unpair_client(target->uuid));
  EXPECT_FALSE(trusted(PUBLIC_CERT));
  EXPECT_TRUE(trusted(other_cert()));
  EXPECT_EQ(get_all_clients().size(), 1u);
}

TEST_F(ClientAuthStateTest, EraseAllWithFailedWriteRevokes) {
  block_state_writes();

  EXPECT_FALSE(erase_all_clients());

  EXPECT_FALSE(trusted(PUBLIC_CERT));
  EXPECT_FALSE(trusted(other_cert()));
  EXPECT_TRUE(get_all_clients().empty());
}

TEST_F(ClientAuthStateTest, UpdateWithFailedWriteChangesInMemoryAndFails) {
  block_state_writes();

  EXPECT_FALSE(update_device_info(target->uuid, "renamed", "", {}, {}, crypto::PERM::_no, true, true, false));

  auto clients = get_all_clients();
  auto client = std::find_if(clients.begin(), clients.end(), [this](const auto &node) {
    return node["uuid"] == target->uuid;
  });
  ASSERT_TRUE(client != clients.end());
  EXPECT_EQ((*client)["name"].get<std::string>(), "renamed");
  EXPECT_EQ((*client)["perm"].get<uint32_t>(), static_cast<uint32_t>(crypto::PERM::_no));
}

TEST_F(ClientAuthStateTest, AddWithDamagedFileTrustsInMemory) {
  ASSERT_TRUE(unpair_client(target->uuid));
  damage_state_file();

  add_authorized_client(make_client(PUBLIC_CERT));

  EXPECT_TRUE(trusted(PUBLIC_CERT));
  EXPECT_EQ(get_all_clients().size(), 2u);
}

TEST_F(ClientAuthStateTest, AddWithFailedWriteTrustsInMemory) {
  ASSERT_TRUE(unpair_client(target->uuid));
  block_state_writes();

  add_authorized_client(make_client(PUBLIC_CERT));

  EXPECT_TRUE(trusted(PUBLIC_CERT));
  EXPECT_EQ(get_all_clients().size(), 2u);
}

TEST_F(ClientAuthStateTest, SaveStateReportsFailure) {
  EXPECT_TRUE(save_state());

  block_state_writes();
  EXPECT_FALSE(save_state());
  std::filesystem::remove(state_file.string() + ".tmp");

  damage_state_file();
  EXPECT_FALSE(save_state());
}

TEST_F(ClientAuthStateTest, LoadStateWithDamagedFileKeepsClientsAndGetsId) {
  damage_state_file();
  http::unique_id.clear();

  load_state();

  EXPECT_FALSE(http::unique_id.empty());
  EXPECT_TRUE(trusted(PUBLIC_CERT));
  EXPECT_EQ(get_all_clients().size(), 2u);
}

TEST_F(ClientAuthStateTest, VerifyDuringStateReloads) {
  std::atomic<bool> done {false};

  auto verify_until_done = [&done]() {
    while (!done) {
      trusted(PUBLIC_CERT);
      trusted(other_cert());
      get_all_clients();
    }
  };
  std::thread verify_a {verify_until_done};
  std::thread verify_b {verify_until_done};

  // The other client stays, so unpair never reaches proc::proc.terminate
  auto client = target;
  for (int i = 0; i < 100; ++i) {
    unpair_client(client->uuid);
    client = make_client(PUBLIC_CERT);
    add_authorized_client(client);
  }

  done = true;
  verify_a.join();
  verify_b.join();

  EXPECT_TRUE(trusted(PUBLIC_CERT));
  EXPECT_TRUE(trusted(other_cert()));
  EXPECT_EQ(get_all_clients().size(), 2u);
}

TEST_F(ClientAuthStateTest, LoadStateReadsStringifiedValues) {
  nlohmann::json client = {
    {"name", "phone"},
    {"cert", other_cert()},
    {"uuid", "u1"},
    {"perm", "65536"},  // PERM::clipboard_set; bit 0 is reserved and masked off
    {"allow_client_commands", "false"},
    {"enable_legacy_ordering", "true"},
    {"always_use_virtual_display", "false"}
  };
  nlohmann::json tree = {{"root", {{"uniqueid", uuid_util::uuid_t::generate().string()}, {"named_devices", nlohmann::json::array({client})}}}};
  std::ofstream(state_file) << tree.dump();

  EXPECT_NO_THROW(load_state());

  auto clients = get_all_clients();
  ASSERT_EQ(clients.size(), 1u);
  EXPECT_EQ(clients[0]["perm"].get<uint32_t>(), 65536u);
  EXPECT_FALSE(clients[0]["allow_client_commands"].get<bool>());
}

TEST_F(ClientAuthStateTest, LoadStateWithStringNamedDevicesLoadsNoClients) {
  // The old ptree writer saved an empty array as a string
  std::ofstream(state_file) << R"({"root": {"uniqueid": "id", "named_devices": ""}})";

  EXPECT_NO_THROW(load_state());

  EXPECT_TRUE(get_all_clients().empty());
  EXPECT_FALSE(trusted(other_cert()));
}

TEST_F(ClientAuthStateTest, LoadStateSkipsClientWithBadPerm) {
  nlohmann::json client = {{"name", "phone"}, {"cert", other_cert()}, {"uuid", "u1"}, {"perm", "abc"}};
  nlohmann::json tree = {{"root", {{"uniqueid", uuid_util::uuid_t::generate().string()}, {"named_devices", nlohmann::json::array({client})}}}};
  std::ofstream(state_file) << tree.dump();

  EXPECT_NO_THROW(load_state());

  EXPECT_TRUE(get_all_clients().empty());
  EXPECT_FALSE(trusted(other_cert()));
}

class LaunchSessionTest: public testing::Test {
protected:
  static args_t launch_args(const std::string &rikey, const std::string &mode) {
    return {{"rikey", rikey}, {"rikeyid", "1"}, {"mode", mode}};
  }

  crypto::named_cert_t cert {"phone", "client-uuid"};
  const std::string key16 = "00112233445566778899aabbccddeeff";
};

TEST_F(LaunchSessionTest, RejectsWrongRikeyLength) {
  EXPECT_THROW(make_launch_session(false, false, launch_args("0011223344556677", "1920x1080x60"), &cert), std::invalid_argument);
  EXPECT_NO_THROW(make_launch_session(false, false, launch_args(key16, "1920x1080x60"), &cert));
}

TEST_F(LaunchSessionTest, DisplayModeFallsBackWhenInvalid) {
  for (const char *mode : {"2556x1179", "0x0x0"}) {
    auto session = make_launch_session(false, false, launch_args(key16, mode), &cert);
    EXPECT_EQ(session->width, 1920) << mode;
    EXPECT_EQ(session->height, 1080) << mode;
    EXPECT_EQ(session->fps, 60000) << mode;
  }
}

TEST_F(LaunchSessionTest, ParsesValidDisplayMode) {
  auto session = make_launch_session(false, false, launch_args(key16, "2556x1179x60"), &cert);
  EXPECT_EQ(session->width, 2556);
  EXPECT_EQ(session->height, 1178);
  EXPECT_EQ(session->fps, 60000);
}

TEST_F(LaunchSessionTest, RoundsOddDimensionsToEven) {
  auto portrait = make_launch_session(false, false, launch_args(key16, "1179x2556x60"), &cert);
  EXPECT_EQ(portrait->width, 1178);
  EXPECT_EQ(portrait->height, 2556);
}

TEST_F(LaunchSessionTest, NegativeModeFallsBack) {
  auto session = make_launch_session(false, false, launch_args(key16, "-1x-1x60"), &cert);
  EXPECT_EQ(session->width, 1920);
  EXPECT_EQ(session->height, 1080);
}

TEST_F(LaunchSessionTest, InvalidScaleFactorBecomes100) {
  for (const char *sf : {"0", "401"}) {
    auto args = launch_args(key16, "1920x1080x60");
    args.emplace("scaleFactor", sf);
    EXPECT_EQ(make_launch_session(false, false, args, &cert)->scale_factor, 100u) << sf;
  }
}
